CHIL_STATUS chil_ec_measure(chil_ec_config* sensor, chil_ec_result* result, uint8_t averages) {

	HAL_StatusTypeDef hal_status;
	result->ready = 0;

	// Configure the HAL in case we have used the ADC for something else
	__chil_ec_stm32_hal_setup(sensor);

	// Start timer
	hal_status = HAL_TIM_Base_Start(sensor->timer_handle);
	if (hal_status != HAL_OK) return CHIL_ERROR;
	hal_status = HAL_TIM_PWM_Init(sensor->timer_handle);
	if (hal_status != HAL_OK) return CHIL_ERROR;
	hal_status = HAL_TIM_PWM_Start(sensor->timer_handle, sensor->timer_pwm_channel);
	if (hal_status != HAL_OK) return CHIL_ERROR;
	hal_status = HAL_TIMEx_PWMN_Start(sensor->timer_handle, sensor->timer_pwm_channel);
	if (hal_status != HAL_OK) return CHIL_ERROR;
	hal_status = HAL_TIM_OC_Start(sensor->timer_handle, sensor->timer_adc_channel);
	if (hal_status != HAL_OK) return CHIL_ERROR;

	// Enable op-amp
	hal_status = HAL_OPAMP_Start(sensor->opamp_handle);
	if (hal_status != HAL_OK) return CHIL_ERROR;

	// Enable ADC
	hal_status = HAL_ADC_Start(sensor->adc_handle);
	if (hal_status != HAL_OK) return CHIL_ERROR;

	// Perform averaging
	uint8_t average_count = 0;
	uint32_t ec_average = 0;
	while (average_count++ < averages) {
		HAL_ADC_PollForConversion(sensor->adc_handle, CHIL_EC_ADC_TIMEOUT);
		ec_average += (uint16_t) HAL_ADC_GetValue(sensor->adc_handle);
	}
	// Fix average
	if (average_count > 0) ec_average /= average_count;

	result->averages = average_count;
	result->result = ec_average;
	result->ready = 1;

	// Disable ADC
	hal_status = HAL_ADC_Stop(sensor->adc_handle);
	if (hal_status != HAL_OK) return CHIL_ERROR;
	// Disable op-amp
	hal_status = HAL_OPAMP_Stop(sensor->opamp_handle);
	if (hal_status != HAL_OK) return CHIL_ERROR;

	// Stop timer
	hal_status = HAL_TIM_Base_Stop(sensor->timer_handle);
	if (hal_status != HAL_OK) return CHIL_ERROR;
	hal_status = HAL_TIM_PWM_Stop(sensor->timer_handle, sensor->timer_pwm_channel);
	if (hal_status != HAL_OK) return CHIL_ERROR;
	hal_status = HAL_TIMEx_PWMN_Stop(sensor->timer_handle, sensor->timer_pwm_channel);
	if (hal_status != HAL_OK) return CHIL_ERROR;
	hal_status = HAL_TIM_OC_Stop(sensor->timer_handle, sensor->timer_adc_channel);
	if (hal_status != HAL_OK) return CHIL_ERROR;

	return CHIL_OK;

}

