CHIL_STATUS chil_battery_voltage_read(ADC_HandleTypeDef* adc_handle, uint16_t* battery_voltage) {

	// Variable definitions
	HAL_StatusTypeDef hal_status;
	uint16_t adc_value;

	// Initialise ADC for conversion
	if (chil_battery_voltage_init(adc_handle) != CHIL_OK) return CHIL_ERROR;

	// start ADC conversion
	hal_status = HAL_ADC_Start(adc_handle);
	if (hal_status != HAL_OK) return CHIL_ERROR;

	// poll ADC until conversion completes - note that we should check for the success of the conversion here really
	hal_status = HAL_ADC_PollForConversion(adc_handle, 100);
	if (hal_status != HAL_OK) return CHIL_ERROR;

	// get result
	adc_value = HAL_ADC_GetValue(adc_handle);
	// switch off ADC
	hal_status = HAL_ADC_Stop(adc_handle);
	if (hal_status != HAL_OK) return CHIL_ERROR;

	// convert the ADC value to the supply voltage (VDDA/VREF+), which on Cryowurst is the raw battery voltage
	// we use this handy macro from the HAL
	*battery_voltage = __HAL_ADC_CALC_VREFANALOG_VOLTAGE(adc_value,  ADC_RESOLUTION_12B);
	return CHIL_OK;

}

CHIL_STATUS chil_instrument_init(chil_instrument_config* config, RTC_HandleTypeDef* rtc) {
	// Assign the RTC handle
	config->rtc = rtc;

	uint8_t start_from_reset = 0;
	if(__HAL_PWR_GET_FLAG(PWR_FLAG_SB) != RESET)
//	if(__HAL_PWR_GET_FLAG(PWR_SR1_SBF) != RESET)
	{
		// Clear Standby flag
		DEBUG_PRINTF("Start from shutdown\n");
		__HAL_PWR_CLEAR_FLAG(PWR_FLAG_SB);
//		__HAL_PWR_CLEAR_FLAG(PWR_SR1_SBF);
	} else start_from_reset = 1;
	/* The Following Wakeup sequence is highly recommended prior to each Standby mode entry
	* mainly  when using more than one wakeup source this is to not miss any wakeup event.
	* - Disable all used wakeup sources,
	* - Clear all related wakeup flags,
	* - Re-enable all used wakeup sources,
	* - Enter the Standby mode.
	* */
	/* Disable all used wakeup sources*/
	HAL_RTCEx_DeactivateWakeUpTimer(config->rtc);
	/* Clear all related wakeup flags */
	__HAL_PWR_CLEAR_FLAG(PWR_FLAG_WU);

	// Enable backup registers
	HAL_PWR_EnableBkUpAccess();

	// Read sequence and deployment count registers
	config->transmit_sequence  = HAL_RTCEx_BKUPRead(rtc, CHIL_INSTRUMENT_BKUP_SEQUENCE);
	config->deployment_packets = HAL_RTCEx_BKUPRead(rtc, CHIL_INSTRUMENT_BKUP_DEPLOYMENT);

	return CHIL_OK;

}

void chil_instrument_sleep(chil_instrument_config* config) {
	 // Enable backup access
	HAL_PWR_EnableBkUpAccess();
	// Write the config variables to the backup
	HAL_RTCEx_BKUPWrite(config->rtc, CHIL_INSTRUMENT_BKUP_SEQUENCE, config->transmit_sequence);
	HAL_RTCEx_BKUPWrite(config->rtc, CHIL_INSTRUMENT_BKUP_DEPLOYMENT, config->deployment_packets);
	//
	uint32_t sleep_period_s = config->long_term_sleep_period_s;
	if (config->deployment_packets < config->max_deployment_packets) {
		sleep_period_s = config->deployment_sleep_period_s;
		DEBUG_PRINTF("Sleep mode [DEPLOY (%d)] for %d seconds\n", sleep_period_s, config->deployment_packets);
	} else {
		DEBUG_PRINTF("Sleep mode [LONG TERM] for %d seconds\n", sleep_period_s);
	}

	HAL_RTCEx_SetWakeUpTimer_IT(config->rtc, sleep_period_s, RTC_WAKEUPCLOCK_CK_SPRE_16BITS);

	// Finally, enter shutdown mode
	HAL_PWREx_EnterSHUTDOWNMode();
}
